 'use client';import{useEffect,useState}from'react';import{api}from'../../lib/api';export default function Support(){const[t,setT]=useState<any[]>([]),[sel,setSel]=useState<any>(),[sub,setSub]=useState(''),[msg,setMsg]=useState(''),[reply,setReply]=useState(''),[e,setE]=useState('');async function load(){try{setT(await api('/api/vendor/support/tickets'))}catch(x:any){setE(x.message)}}useEffect(()=>{load()},[]);async function create(){try{await api('/api/vendor/support/tickets',{method:'POST',body:JSON.stringify({subject:sub,description:msg})});setSub('');setMsg('');load()}catch(x:any){setE(x.message)}}async function send(){try{await api(`/api/vendor/support/tickets/${sel.id}/messages`,{method:'POST',body:JSON.stringify({message:reply})});setReply('');setSel(await api(`/api/vendor/support/tickets/${sel.id}`));load()}catch(x:any){setE(x.message)}}return <main className="shell"><div className="page-heading-row"><div><div className="eyebrow">VENDOR SUPPORT</div><h1>Support</h1><p className="muted">Get help with orders, payouts, riders, onboarding and technical issues.</p></div></div>{e&&<div className="error">{e}</div>}<div className="support-grid"><section className="content-card support-create"><div className="card-head"><div><span>CONTACT ROZZI</span><h2>Open a ticket</h2></div></div><label>Subject<input className="input" value={sub} onChange={x=>setSub(x.target.value)} placeholder="What do you need help with?"/></label><label>Message<textarea className="input" rows={6} value={msg} onChange={x=>setMsg(x.target.value)} placeholder="Describe the issue…"/></label><button className="btn" disabled={!sub.trim()||!msg.trim()} onClick={create}>Create ticket</button></section><section className="content-card"><div className="card-head"><div><span>YOUR CASES</span><h2>Support tickets</h2></div></div>{t.map(x=><button className={`ticket-row ${sel?.id===x.id?'active':''}`} key={x.id} onClick={async()=>setSel(await api(`/api/vendor/support/tickets/${x.id}`))}><div><strong>{x.subject}</strong><small>{new Date(x.updatedAt).toLocaleDateString('en-NG')}</small></div><span className={`ticket-status ${x.status.toLowerCase()}`}>{x.status.replace(/_/g,' ')}</span></button>)}</section></div>{sel&&<section className="content-card support-thread"><div className="card-head"><div><span>TICKET</span><h2>{sel.subject}</h2></div><span className={`ticket-status ${sel.status.toLowerCase()}`}>{sel.status.replace(/_/g,' ')}</span></div><div className="thread">{sel.messages?.map((m:any)=><div className={`message-bubble ${m.isAdmin?'admin':''}`} key={m.id}><small>{m.isAdmin?'ROZZI Support':'You'}</small><p>{m.message}</p></div>)}</div>{!['CLOSED','RESOLVED'].includes(sel.status)&&<div className="reply-row"><textarea className="input" rows={3} value={reply} onChange={x=>setReply(x.target.value)} placeholder="Reply…"/><button className="btn" disabled={!reply.trim()} onClick={send}>Send</button></div>}</section>}</main>}